const collectionData=[
{id:'sandwiches-salads',title:'Sandwiches & salads',short:'Sandwiches & salads',kicker:'THE LUNCH TABLE',image:'platter',type:'delivery',service:'Delivered & ready to serve',occasion:'Meetings · lunches · celebrations',desc:'A ready-to-share selection for work lunches, birthdays and relaxed get-togethers. Delivered platters make it easy to bring everyone around the table.',highlights:['A choice of sandwich breads and fillings','Individual salads and sharing platters','Delivery-only catering'],source:'https://www.feastcateringnewcastle.com.au/sandwich-salads',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_2fd240c15c2c4052b0f28592382b4f4b.pdf',note:'The published menu specifies a five-sandwich minimum. Confirm delivery fees, dietary requests and Sunday or public-holiday charges with Tracy.'},
{id:'breakfast-tea',title:'Breakfast, morning & afternoon tea',short:'Breakfast & tea',kicker:'START SOMETHING GOOD',image:'breakfast',type:'delivery',service:'Delivered & ready to serve',occasion:'Early meetings · morning tea · afternoon catch-ups',desc:'From a morning meeting to an afternoon catch-up, explore sweet and savoury selections delivered ready for the table.',highlights:['Pastries and breakfast selections','Scones, cakes and small sweet treats','Granola cups and fruit platters'],source:'https://www.feastcateringnewcastle.com.au/breakfast-morning-tea-afternoon-tea',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_bb6e20ad7ba44956b3fa3102d738decd.pdf?index=true',note:'Share your requested delivery time and dietary questions with the team. Menu availability, GST and delivery charges need confirmation.'},
{id:'finger-food-delivery',title:'Finger food delivery',short:'Finger food delivery',kicker:'LITTLE BITES. BIG OCCASIONS.',image:'canapes',type:'delivery',service:'Delivered for you to serve',occasion:'Small parties · relaxed entertaining',desc:'Prepared finger-food platters for hosts who want to handle the serving themselves. Feast’s delivery menu is intended for gatherings of up to 20 guests.',highlights:['Prepared platters delivered to your door','A mix of savoury finger-food choices','Self-service entertaining'],source:'https://www.feastcateringnewcastle.com.au/finger-food-delivery',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_32af70d8b7144a66b2f41c106fe07fc8.pdf',note:'Check platter sizes, minimum quantities and delivery arrangements in the menu, then confirm the details with Tracy.'},
{id:'finger-food-venue',title:'Finger food at your venue',short:'Finger food venue catering',kicker:'YOU ENJOY THE PARTY',image:'canapes',type:'venue',service:'Prepared & served at your venue',occasion:'Cocktail parties · events · celebrations',desc:'Let the catering team prepare and serve while you spend time with your guests. A canapé-led menu designed for a relaxed, social occasion.',highlights:['A selection of canapés for your event','On-site food preparation and service','Clean-down after service'],source:'https://www.feastcateringnewcastle.com.au/winter-2026-finger-food-menu',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_f5af0563f90e43359cfcb9c3aa76541e.pdf',note:'Published requirements include at least 20 guests and seven canapé selections. Staff, travel, hire and surcharge details are confirmed for each event.'},
{id:'banquet',title:'Banquet feasts',short:'Banquet',kicker:'GATHER. SHARE. CELEBRATE.',image:'wedding',type:'venue',service:'Prepared & served in your home',occasion:'Family gatherings · celebrations',desc:'Gather friends and family for a generous shared meal. Feast takes care of cooking, serving and the kitchen clean-down so you can enjoy the occasion.',highlights:['Classic and premium banquet choices','A shared meal for friends and family','On-site preparation, service and clean-down'],source:'https://www.feastcateringnewcastle.com.au/banquet-menu',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_18ebaec62d0e449193f513449b06f17e.pdf',note:'Check the current banquet options with Tracy. Staffing, GST, travel, equipment and any event-day surcharges are additional considerations.'},
{id:'gourmet-bbq',title:'Gourmet BBQ',short:'Gourmet BBQ',kicker:'FIRE UP THE GATHERING',image:'bbq',type:'venue',service:'Cooked & served at your home',occasion:'Outdoor gatherings · family celebrations',desc:'A shared BBQ with grilled meats, sides and salads. Feast prepares and serves the meal at your home, with clean-down after the gathering.',highlights:['Grilled meat and chicken selections','Fresh sides, salads and accompaniments','Preparation, serving and kitchen clean-down'],source:'https://www.feastcateringnewcastle.com.au/family-feast',pdf:'https://www.feastcateringnewcastle.com.au/_files/ugd/4fee5a_cd751b46695d439bae444d8560decafa.pdf',note:'The published BBQ menu has a 25-guest minimum. Confirm staffing, GST, travel, equipment and Sunday or public-holiday charges before booking.'},
{id:'dinner-party',title:'Dinner parties',short:'Dinner party',kicker:'MAKE A NIGHT OF IT',image:'wedding',type:'private',service:'Chef-led dining',occasion:'Intimate dinners · special evenings',desc:'Enjoy a dinner-party menu with a professional chef. Explore entrée, main and dessert choices, and discuss the courses that suit your evening.',highlights:['Two-course and three-course choices','A professional chef included','Service staff available at extra cost'],source:'https://www.feastcateringnewcastle.com.au/dinner-party',pdf:null,note:'Ask Tracy about the current menu, pricing and availability. Service staff and GST are additional to the published package prices.'}
];
let activeCollectionFilter='all';
function collectionImage(c,cls=''){return `<img class="${cls}" src="/images/${c.image}.jpg" alt="${esc(c.title)} food and event inspiration" loading="lazy" width="1400" height="1000">`}
function menuTile(c,i=0){return `<a class="collection-tile" href="/menus/${c.id}" data-route>${collectionImage(c)}<div class="tile-shade"></div><span class="tile-number">0${i+1}</span><span class="tile-service">${c.type==='delivery'?'DELIVERED':c.type==='private'?'PRIVATE DINING':'AT YOUR VENUE'}</span><div class="tile-copy"><small>${c.kicker}</small><h3>${c.title}</h3><span>Explore this menu <b>↗</b></span></div></a>`}
function menuDirectory(){let items=collectionData.filter(c=>activeCollectionFilter==='all'||c.type===activeCollectionFilter);return `<div class="menu-directory"><section class="directory-intro"><div><a class="backlink" href="/" data-route>HOME / MENUS</a><div class="eyebrow">FEAST CATERING · NEWCASTLE & THE HUNTER</div><h1>Every gathering.<br><em>A different feast.</em></h1><p>From the first coffee to the last canapé. Find a menu that feels right for your occasion.</p><div class="directory-count"><strong>07</strong><span>WAYS TO FEAST<br>ONE THOUGHTFUL TEAM</span></div></div><div class="directory-intro-photo"><img src="/images/canapes.jpg" alt="Colourful finger-food platters with fresh ingredients" width="1400" height="1000"><span class="directory-stamp">SOMETHING<br><i>delicious</i><br>FOR EVERY OCCASION</span></div></section><div class="directory-body"><div class="directory-toolbar"><div class="filter-pills" aria-label="Filter catering menus">${[['all','All menus'],['delivery','Delivered to you'],['venue','At your venue'],['private','Private dining']].map(([id,l])=>`<button data-collection-filter="${id}" class="${activeCollectionFilter===id?'is-active':''}" aria-pressed="${activeCollectionFilter===id}">${l}</button>`).join('')}</div><span>${items.length} ${items.length===1?'menu':'menus'} to explore</span></div><div class="collection-grid ${activeCollectionFilter==='all'?'all-menus':''}">${items.map(menuTile).join('')}</div><div class="directory-help"><div><span class="eyebrow">NOT SURE WHERE TO START?</span><h2>Tell us about your occasion.<br><em>We'll talk food.</em></h2></div><a href="/contact" data-route class="btn">Plan an event with Tracy <span>↗</span></a></div></div></div>`}
function collectionPage(id){let c=collectionData.find(x=>x.id===id);if(!c)return menuDirectory();return `<div class="collection-detail"><section class="collection-hero">${collectionImage(c)}<div class="collection-hero-shade"></div><div><a class="backlink" href="/menu" data-route>← ALL MENUS</a><div class="eyebrow">${c.kicker}</div><h1>${c.title}</h1><p>${c.occasion}</p><span class="service-pill">${c.service}</span></div></section><div class="collection-content"><article><div class="eyebrow">A MENU FOR THE MOMENT</div><h2>A little more flavour.<br><em>A lot more together.</em></h2><p>${c.desc}</p><div class="collection-highlights">${c.highlights.map((h,i)=>`<div><span>0${i+1}</span><h3>${h}</h3></div>`).join('')}</div><div class="collection-note"><h3>The details matter.</h3><p>${c.note}</p><p>Discuss dietary suitability and cross-contact with the catering team before confirming your menu.</p></div>${c.id==='sandwiches-salads'?'<a class="btn" href="/lunch" data-route>Build a lunch request <span>↗</span></a>':''}</article><aside class="menu-plan-card"><span class="tinytitle">LET'S PLAN YOUR FEAST</span><h3>Your occasion.<br>Our next conversation.</h3><p>Share your date, guest count and venue so Tracy can help with the next step.</p><a class="btn" href="/contact?menu=${c.id}" data-route>Prepare an enquiry <span>↗</span></a>${c.pdf?`<a class="menu-download" href="${c.pdf}" target="_blank" rel="noopener">View menu & order form PDF <span>↓</span></a>`:`<a class="menu-download" href="${c.source}" target="_blank" rel="noopener">View dinner-party menu <span>↗</span></a>`}<div class="plan-contact">Tracy Roddenby<br><strong>0417 299 816</strong><br><span>tracy@feastcateringnewcastle.com.au</span></div></aside></div><section class="more-menus"><div class="sectionhead"><div><div class="eyebrow">KEEP EXPLORING</div><h2>A few more ways to feast.</h2></div><a class="quietlink" href="/menu" data-route>All menus ↗</a></div><div>${collectionData.filter(x=>x.id!==id).slice(0,3).map(menuTile).join('')}</div></section></div>`}
function servicesSection(){return `<section class="feast-occasions"><div class="food-container"><div class="sectionhead reveal"><div><div class="eyebrow">FOR EVERY KIND OF GATHERING</div><h2>Big days.<br><em>Little moments.</em></h2></div><p>Newcastle, the Hunter region and beyond. Food for the occasions that bring people together.</p></div><div class="occasion-cards"><a href="/weddings" data-route>${collectionImage({title:'Wedding table',image:'wedding'})}<div><small>YOUR DAY. YOUR PEOPLE.</small><h3>Weddings</h3><span>Make it memorable ↗</span></div></a><a href="/functions" data-route>${collectionImage({title:'Corporate catering',image:'platter'})}<div><small>GOOD FOOD GETS PEOPLE TALKING</small><h3>Corporate events</h3><span>Bring the team together ↗</span></div></a><a href="/functions#celebrations" data-route>${collectionImage({title:'Party finger food',image:'canapes'})}<div><small>AN OCCASION WORTH SHARING</small><h3>Private celebrations</h3><span>Plan your celebration ↗</span></div></a></div></div></section>`}
function aboutPage(){return `<div class="editorial-page"><section class="editorial-head"><div><div class="eyebrow">THE PEOPLE BEHIND THE FEAST</div><h1>Good food.<br><em>Thoughtful people.</em></h1><p>Meet Tracy Roddenby and the Feast Catering team, catering for gatherings across Newcastle, the Hunter region and beyond.</p></div><img src="/images/platter.jpg" alt="A sharing platter of freshly filled sandwiches" width="1400" height="1000"></section><section class="editorial-story"><div><div class="eyebrow">FEAST CATERING</div><h2>A gathering starts<br><em>with the people.</em></h2></div><div><p>From family occasions and weddings to boardroom meetings and corporate celebrations, Tracy and her team cater for events both small and large.</p><p>Feast can bring cooking facilities to a range of settings, including homes, outdoor locations and function venues. Talk with Tracy about your location and the kind of service you need.</p><a class="btn" href="/contact" data-route>Tell us about your occasion ↗</a></div></section>${servicesSection()}</div>`}
function functionsPage(){return `<div class="editorial-page"><section class="editorial-head"><div><div class="eyebrow">FEAST FUNCTIONS</div><h1>For the moments<br><em>that matter.</em></h1><p>Something to celebrate. A team to bring together. Find the food and service style that fits your event.</p><a class="btn" href="/contact" data-route>Plan your event ↗</a></div><img src="/images/canapes.jpg" alt="Food platters for celebrations and events" width="1400" height="1000"></section><section class="event-types" id="celebrations"><article><span>01 / PRIVATE CELEBRATIONS</span><h2>Your people.<br>Your occasion.</h2><p>Weddings, engagements, birthdays, baby showers and christenings. Bring friends and family together around food.</p><a href="/menu" data-route>Explore celebration menus ↗</a></article><article><span>02 / CORPORATE EVENTS</span><h2>A good reason<br>to get together.</h2><p>Boardroom meetings, corporate lunches and dinners, launches, openings, expos and presentations.</p><a href="/menus/sandwiches-salads" data-route>Explore lunch catering ↗</a></article><article><span>03 / STAFF & SEASONAL OCCASIONS</span><h2>Mark a milestone.<br>Share a feast.</h2><p>Staff functions, training and team development days, Christmas gatherings, dinner parties and New Year's Eve celebrations.</p><a href="/menus/finger-food-venue" data-route>Explore event catering ↗</a></article></section>${servicesSection()}</div>`}
function weddingsPage(){return `<div class="weddings-page"><section class="wedding-hero"><img src="/images/wedding.jpg" alt="A wedding reception table with candles and flowers" width="1500" height="1000"><div><div class="eyebrow">FEAST WEDDINGS</div><h1>Your favourite people.<br><em>An unforgettable table.</em></h1><p>Food, conversation and a celebration to remember.</p><a class="btn food-orange" href="/contact?occasion=wedding" data-route>Let's talk about your day ↗</a></div></section><section class="editorial-story"><div><div class="eyebrow">YOUR DAY, THOUGHTFULLY PLANNED</div><h2>A wedding feast<br><em>that feels like you.</em></h2></div><div><p>Explore finger-food and seated-meal options, with beverage packages and hospitality staff available to discuss for your reception.</p><p>Talk with Tracy about your date, venue, guest count and preferred style. Menu suitability, service arrangements and availability are checked with the team.</p><a class="quietlink" href="/menu" data-route>Explore the menus ↗</a></div></section><div class="wedding-options">${collectionData.filter(c=>['finger-food-venue','banquet','dinner-party'].includes(c.id)).map(menuTile).join('')}</div><section class="directory-help"><div><div class="eyebrow">LET'S START WITH YOUR STORY</div><h2>Tell us about<br><em>your celebration.</em></h2></div><a class="btn" href="/contact?occasion=wedding" data-route>Prepare a wedding enquiry ↗</a></section></div>`}
function contactPage(){let params=new URLSearchParams(location.search),chosen=collectionData.find(c=>c.id===params.get('menu'));return `<div class="contact-page"><section class="contact-intro"><div class="eyebrow">LET'S TALK FOOD</div><h1>A date. An occasion.<br><em>A delicious beginning.</em></h1><p>Tell Tracy a little about your plans. Bring together the details to start your catering conversation.</p></section><div class="contact-layout"><aside><h2>Feast Catering</h2><p>Newcastle, the Hunter region & beyond.</p><div class="contact-info"><span>YOUR CONTACT</span><strong>Tracy Roddenby</strong><span>PHONE</span><strong>0417 299 816</strong><span>EMAIL</span><strong class="contact-email">tracy@feastcateringnewcastle.com.au</strong></div><img src="/images/canapes.jpg" alt="Small bites and sharing platters" width="900" height="700"><div class="contact-order"><h3>Prefer an order form?</h3><p>Browse the menu, download its order form and email the completed form to Tracy.</p><a class="quietlink" href="/menu" data-route>Find a menu & order form ↗</a></div></aside><form id="enquiry-form" class="panel"><h2>About your gathering</h2><div class="fields"><div class="field"><label for="enq-name">Your name *</label><input id="enq-name" name="name" required maxlength="80"></div><div class="field"><label for="enq-email">Email address *</label><input id="enq-email" name="email" type="email" required maxlength="254"></div><div class="field"><label for="enq-phone">Phone number</label><input id="enq-phone" name="phone" type="tel" maxlength="30"></div><div class="field"><label for="enq-date">Requested date</label><input id="enq-date" name="date" type="date"></div><div class="field"><label for="enq-guests">Estimated guests</label><input id="enq-guests" name="guests" type="number" min="1" max="10000"></div><div class="field"><label for="enq-menu">Menu or occasion</label><select name="menu" id="enq-menu"><option>Not sure yet</option>${collectionData.map(c=>`<option ${chosen?.id===c.id?'selected':''}>${c.title}</option>`).join('')}<option ${params.get('occasion')==='wedding'?'selected':''}>Wedding catering</option></select></div><div class="field full"><label for="enq-location">Venue or location</label><input name="location" id="enq-location" maxlength="200"></div><div class="field full"><label for="enq-message">What do you have in mind? *</label><textarea id="enq-message" name="message" required rows="5" maxlength="1500"></textarea><span class="help">Include your preferred service style and any dietary questions for the team.</span></div></div><button type="submit" class="btn">Prepare my enquiry ↗</button><p class="help">Prepare a summary to copy into your email to Tracy.</p><div id="enquiry-result" role="status"></div></form></div></div>`}
function buildNav(){let nav=document.querySelector('#site-navigation');if(!nav)return;nav.innerHTML=`<details class="nav-dropdown nav-menus"><summary><span>Our menus</span><i class="nav-chevron" aria-hidden="true"></i></summary><div class="mega-menu"><div class="mega-intro"><span class="eyebrow">FIND YOUR KIND OF FEAST</span><h2>Good food.<br><em>Every occasion.</em></h2><p>Seven ways to bring your people together.</p><a href="/menu" data-route>Discover all menus <span>↗</span></a></div><div class="mega-links">${collectionData.map((c,i)=>`<a href="/menus/${c.id}" data-route><small>0${i+1}</small><span>${c.short}</span><b>↗</b></a>`).join('')}</div><a class="mega-photo" href="/weddings" data-route><img src="/images/wedding.jpg" alt="Wedding table" width="500" height="500"><span><small>YOUR PEOPLE. YOUR CELEBRATION.</small>Feast weddings <b>↗</b></span></a></div></details><a href="/lunch" data-route class="nav-lunch">Plan lunch <span class="request-count">0</span></a><a href="/functions" data-route>Occasions</a><a href="/weddings" data-route>Weddings</a><a href="/about" data-route>Our story</a><a href="/contact" data-route class="mobile-contact">Get in touch <span>↗</span></a><div class="nav-mobile-bottom"><span>NEWCASTLE & THE HUNTER</span><a href="/contact" data-route>Let's make it a feast <b>↗</b></a></div>`}
